function getTriggerInput() {
  try { return $('Receive workflow call').first().json; } catch (error) {}
  try { return $('Receive request').first().json; } catch (error) {}
  return $json;
}
const inputRoot = getTriggerInput();
const input = inputRoot.body ?? inputRoot;
const ai = $json;
const executionId = typeof $execution !== 'undefined' && $execution.id ? $execution.id : Date.now();
const requestId = input.request_id || input.live_probe?.request_id || 'req_' + executionId;
const aiText = ai.output || ai.text || ai.response || ai.message || '';
const isResume = input.intent === 'resume_after_approval' || input.input?.approved === true;
const query = String(input.input?.query || input.input?.message || input.query || input.message || input.chatInput || '').toLowerCase();

function safeJson(value) {
  if (value && typeof value === 'object') return value;
  const text = String(value || '').trim();
  if (!text) return null;
  const fenced = text.match(/```(?:json)?\s*([\s\S]*?)```/i);
  const candidate = (fenced ? fenced[1] : text).trim();
  const firstBrace = candidate.indexOf('{');
  const lastBrace = candidate.lastIndexOf('}');
  if (firstBrace < 0 || lastBrace <= firstBrace) return null;
  try { return JSON.parse(candidate.slice(firstBrace, lastBrace + 1)); } catch { return null; }
}

function explicitSkillCreationIntent(text) {
  return /\b(create|shape|design|generate|build|define|propose|draft)\b[\s\S]{0,64}\b(new\s+)?(skill|agent|task-agent|task agent|subagent|sub-agent|capability)\b/i.test(text)
    || /\b(new|additional)\s+(skill|agent|task-agent|task agent|subagent|sub-agent|capability)\b/i.test(text)
    || /\b(skill|agent|task-agent|task agent|subagent|sub-agent|capability)\b[\s\S]{0,64}\b(create|shape|design|generate|build|define|propose|draft)\b/i.test(text);
}

function cleanParsedOutput(parsed, text) {
  const envelope = parsed && typeof parsed === 'object' ? parsed : {};
  const output = envelope.output && typeof envelope.output === 'object' ? envelope.output : envelope;
  const result = { ...output };
  if (!result.next_question && result.result?.next_question) result.next_question = result.result.next_question;
  if (!result.question_type && result.result?.question_type) result.question_type = result.result.question_type;
  if (!result.gap_being_closed && result.result?.gap_being_closed) result.gap_being_closed = result.result.gap_being_closed;
  if (!result.summary && envelope.answer) result.summary = envelope.answer;
  if (!result.summary && envelope.summary) result.summary = envelope.summary;
  if (result.email_draft?.subject && !result.summary) result.summary = 'Drafted email: ' + result.email_draft.subject;
  if (!result.summary && result.next_question) result.summary = result.next_question;
  if (!result.summary && result.skill_invoked) result.summary = String(result.skill_invoked) + ' completed.';
  if (!result.next_question && result.result?.next_question) result.next_question = result.result.next_question;
  if (!result.question_type && result.result?.question_type) result.question_type = result.result.question_type;
  if (!result.gap_being_closed && result.result?.gap_being_closed) result.gap_being_closed = result.result.gap_being_closed;
if (!result.summary && result.next_question) result.summary = result.next_question;
  if (!result.summary && result.skill_invoked) result.summary = String(result.skill_invoked) + ' completed.';
  if (!result.next_question && result.result?.next_question) result.next_question = result.result.next_question;
  if (!result.question_type && result.result?.question_type) result.question_type = result.result.question_type;
  if (!result.gap_being_closed && result.result?.gap_being_closed) result.gap_being_closed = result.result.gap_being_closed;
if (!result.summary && result.next_question) result.summary = result.next_question;
  if (!result.summary && result.skill_invoked) result.summary = String(result.skill_invoked) + ' completed.';
  if (!result.summary) result.summary = text || 'Agentic Butler completed autonomous skill orchestration under Actor Twin steering.';
  if (typeof result.summary === 'string' && /^```|^\s*\{/.test(result.summary) && (result.artifact || result.task_trace || result.execution_plan)) {
    result.summary = result.artifact?.title || result.result?.title || 'Skill orchestration completed.';
  }
  if (result.summary === text && (result.next_question || result.skill_invoked || result.okf_candidate || result.result?.next_question)) {
    result.summary = result.next_question || (String(result.skill_invoked) + ' completed.');
  }
  if (result.summary === text && (result.next_question || result.skill_invoked || result.okf_candidate || result.result?.next_question)) {
    result.summary = result.next_question || (String(result.skill_invoked) + ' completed.');
  }
  if (result.summary === text && (result.next_question || result.skill_invoked || result.okf_candidate || result.result?.next_question)) {
    result.summary = result.next_question || (String(result.skill_invoked) + ' completed.');
  }
  return result;
}

const parsed = safeJson(aiText);
const aiOutput = cleanParsedOutput(parsed, aiText);
const routeDecision = input.context?.route_decision || {};
const explicitCreation = explicitSkillCreationIntent(query);
const isCreateSkill = explicitCreation || (input.intent === 'create_skill' && routeDecision.decision === 'create_skill');
const approvalRequired = !isResume && isCreateSkill;
const approval = approvalRequired ? {
  required: true,
  gate: 'skill_spec_approval',
  summary: 'Generated skill or agent proposal is ready for human review.',
  proposed_action: 'Approve the proposal to stage SkillSpec decomposition and make the generated capability available through Agentic Butler orchestration.'
} : { required: false };
const skillCreation = approvalRequired ? {
  status: 'proposal_pending_approval',
  mode_of_action: aiOutput.mode_of_action || aiOutput.skill_creation?.mode_of_action || 'Agentic Butler elicits, decomposes, and stages a generated skill or agent behind approval.',
  value_proposition: aiOutput.value_proposition || aiOutput.skill_creation?.value_proposition || 'Transforms repeated work into reusable Actor Twin capability.',
  usp: aiOutput.usp || aiOutput.skill_creation?.usp || 'Compares the proposed capability against existing skills and activates only after human ratification.',
  decomposition_outline: aiOutput.decomposition_outline || aiOutput.skill_creation?.decomposition_outline || []
} : null;
const response = {
  envelope_version: input.envelope_version || '0.1.0',
  request_id: requestId,
  agent_id: 'agentic_butler',
  status: approvalRequired ? 'approval_required' : 'completed',
  approval,
  output: {
    ...aiOutput,
    summary: aiOutput.summary,
    approval_request: approvalRequired ? approval : null,
    skill_run: aiOutput.skill_run || { mode: isResume ? 'resumed_after_approval' : approvalRequired ? 'approval_gated_new_skill_or_agent' : 'autonomous_actor_delegated', execute: !approvalRequired },
    skill_creation: skillCreation,
    contract_stage: 'ai_agent_normalized',
    ai_agent: { integrated: true, node: 'Agentic Butler AI Agent' }
  },
  trace: { stored: true, trace_id: 'n8n_exec_' + executionId, used_agents: Array.from(new Set(['agentic_butler_ai_agent', 'skill_orchestrator_internal_component', 'actor_twin_checkpoint_boundary'].concat(parsed?.trace?.used_agents || aiOutput.trace?.used_agents || []).concat((aiOutput.next_question || aiOutput.result?.mode === 'tacit_knowledge_elicitation' || aiOutput.skill_invoked === 'Knowledge Retrieval Interviewer') ? ['knowledge_retrieval_interviewer'] : []).concat((aiOutput.task_trace || aiOutput.execution_plan || aiOutput.artifact) ? ['skill_orchestrator', 'task_agent'] : []))), target_agent: 'agentic_butler', route_decision: isCreateSkill ? 'create_skill' : 'activate_skill', handoff_status: approvalRequired ? 'approval_required' : 'completed_autonomous', parent_trace_id: input.context?.handoff_trace_id || input.context?.actor_trace_id || '', ai_agent_integrated: true }
};
return [{ json: response }];

